<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/document_manager.php';require_once __DIR__.'/includes/project_manager.php';require_permission('clients.view');$id=max(1,(int)($_GET['id']??0));$st=db()->prepare('SELECT c.*,u.name owner_name FROM clients c LEFT JOIN users u ON u.id=c.owner_user_id WHERE c.id=?');$st->execute([$id]);$client=$st->fetch();if(!$client){http_response_code(404);exit('Cliente no encontrado.');}$pageTitle=$client['company_name'];$queries=[];
$st=db()->prepare('SELECT s.*,sc.name_es catalog_name FROM client_services s LEFT JOIN service_catalog sc ON sc.id=s.catalog_service_id WHERE s.client_id=? ORDER BY s.expiration_date IS NULL,s.expiration_date,s.created_at DESC');$st->execute([$id]);$services=$st->fetchAll();$st=db()->prepare("SELECT p.*,u.name owner_name FROM contacts p LEFT JOIN users u ON u.id=p.owner_user_id WHERE p.client_id=? ORDER BY p.status='active' DESC,p.first_name,p.last_name");$st->execute([$id]);$contacts=$st->fetchAll();$st=db()->prepare("SELECT d.*,ps.name_es stage_name,ps.color,u.name owner_name FROM deals d JOIN pipeline_stages ps ON ps.id=d.stage_id LEFT JOIN users u ON u.id=d.owner_user_id WHERE d.client_id=? ORDER BY d.status='open' DESC,d.updated_at DESC");$st->execute([$id]);$deals=$st->fetchAll();$st=db()->prepare('SELECT * FROM quotations WHERE client_id=? ORDER BY issue_date DESC,id DESC LIMIT 20');$st->execute([$id]);$quotes=$st->fetchAll();$st=db()->prepare("SELECT bc.*,s.name service_name FROM billing_charges bc JOIN client_services s ON s.id=bc.service_id WHERE bc.client_id=? ORDER BY bc.due_date DESC LIMIT 30");$st->execute([$id]);$billingCharges=$st->fetchAll();$billingTotals=['CLP'=>0.0,'USD'=>0.0,'BRL'=>0.0];foreach($services as$sv){if($sv['status']==='active'&&$sv['contract_type']==='monthly')$billingTotals[$sv['currency']]+=(float)$sv['amount'];}$st=db()->prepare('SELECT a.*,u.name assigned_name,CONCAT(p.first_name,\' \',COALESCE(p.last_name,\'\')) contact_name,d.title deal_title FROM activities a LEFT JOIN users u ON u.id=a.assigned_to LEFT JOIN contacts p ON p.id=a.contact_id LEFT JOIN deals d ON d.id=a.deal_id WHERE a.client_id=? ORDER BY COALESCE(a.due_at,a.created_at) DESC LIMIT 30');$st->execute([$id]);$activities=$st->fetchAll();$pmProjects=[];if(has_permission('projects.view')){$pq=db()->prepare("SELECT id,name,status,health,progress,due_date FROM projects WHERE client_id=? ORDER BY status='active' DESC,due_date IS NULL,due_date");$pq->execute([$id]);$pmProjects=$pq->fetchAll();}require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-body client-hero"><?php if($client['logo_path']):?><img class="client-logo" src="<?=e($client['logo_path'])?>" alt=""><?php else:?><div class="client-logo placeholder"><?=e(crm_upper(crm_substr($client['company_name'],0,1)))?></div><?php endif;?><div><h2><?=e($client['company_name'])?></h2><p><?=e(($client['country']?:'Sin país').' · '.($client['trade_name']?:$client['industry']?:'Cliente'))?></p><span class="badge badge-<?=$client['status']==='active'?'green':($client['status']==='prospect'?'orange':'gray')?>"><?=e(client_status_label($client['status']))?></span><span class="table-sub">Responsable: <?=e($client['owner_name']?:'Sin asignar')?></span></div><div class="actions"><?php if(has_permission('contacts.manage')):?><a class="btn btn-secondary" href="contact_form.php?client_id=<?=$id?>">+ Contacto</a><?php endif;?><?php if(has_permission('activities.manage')):?><a class="btn btn-secondary" href="activity_form.php?client_id=<?=$id?>">+ Actividad</a><?php endif;?><?php if(has_permission('deals.manage')):?><a class="btn btn-secondary" href="deal_form.php?client_id=<?=$id?>">+ Negocio</a><?php endif;?><?php if(has_permission('quotes.create')):?><a class="btn btn-secondary" href="quotation_form.php?client_id=<?=$id?>">+ Cotización</a><?php endif;?><?php if(has_permission('clients.edit')):?><a class="btn btn-primary" href="client_form.php?id=<?=$id?>">Editar</a><?php endif;?></div></div></section>
<div class="details-grid client-details" style="margin-top:18px"><div class="detail"><small>Identificación</small><strong><?=e($client['tax_id']?:'—')?></strong></div><div class="detail"><small>Email principal</small><strong><?=e($client['email']?:'—')?></strong></div><div class="detail"><small>WhatsApp</small><strong><?=e($client['whatsapp']?:'—')?></strong></div><div class="detail"><small>Ciudad</small><strong><?=e($client['city']?:'—')?></strong></div><div class="detail"><small>Sitio web</small><strong><?=$client['website']?'<a href="'.e($client['website']).'" target="_blank">'.e($client['website']).'</a>':'—'?></strong></div><div class="detail"><small>Idioma</small><strong><?=e(language_label($client['preferred_language']))?></strong></div></div>
<div class="module-tabs" style="margin-top:20px"><a href="#contacts">Contactos (<?=count($contacts)?>)</a><a href="#services">Servicios (<?=count($services)?>)</a><a href="#deals">Negocios (<?=count($deals)?>)</a><a href="#quotes">Cotizaciones (<?=count($quotes)?>)</a><a href="#billing">Facturación</a><a href="#activity">Actividad (<?=count($activities)?>)</a></div>
<section class="panel" id="contacts"><div class="panel-header"><div><h2>Contactos</h2><span class="table-sub">Personas vinculadas a esta empresa.</span></div><?php if(has_permission('contacts.manage')):?><a class="btn btn-light btn-small" href="contact_form.php?client_id=<?=$id?>">+ Contacto</a><?php endif;?></div><div class="table-wrap"><?php if(!$contacts):?><div class="empty">No hay contactos registrados.</div><?php else:?><table class="data-table"><thead><tr><th>Persona</th><th>Cargo</th><th>Email</th><th>Teléfono / WhatsApp</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($contacts as$c):?><tr><td><a class="table-title" href="contact_view.php?id=<?=(int)$c['id']?>"><?=e(trim($c['first_name'].' '.$c['last_name']))?></a></td><td><?=e($c['job_title']?:'—')?></td><td><?=e($c['email']?:'—')?></td><td><?=e($c['whatsapp']?:$c['phone']?:'—')?></td><td><span class="badge badge-<?=$c['status']==='active'?'green':'orange'?>"><?=e($c['status'])?></span></td><td><a class="btn btn-light btn-small" href="contact_view.php?id=<?=(int)$c['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<section class="panel" id="services" style="margin-top:18px"><div class="panel-header"><div><h2>Servicios de clientes</h2><span class="table-sub">Servicios efectivamente contratados; no es el catálogo maestro.</span></div><?php if(has_permission('services.assign')):?><a class="btn btn-primary btn-small" href="service_form.php?client_id=<?=$id?>">+ ASIGNAR SERVICIO</a><?php endif;?></div><div class="table-wrap"><?php if(!$services):?><div class="empty">Este cliente todavía no tiene servicios asignados.</div><?php else:?><table class="data-table"><thead><tr><th>Servicio</th><th>Contrato</th><th>Vencimiento</th><th>Valor</th><th>Pago</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($services as$s):$state=computed_service_status($s);?><tr><td><strong><?=e($s['name'])?></strong><span class="table-sub"><?=e($s['catalog_name']?:'Servicio personalizado')?></span></td><td><?=e(contract_label($s['contract_type']))?></td><td><?=e(format_date($s['expiration_date']))?></td><td><?=e(format_money($s['amount'],$s['currency']))?></td><td><span class="badge badge-<?=e(payment_status_class($s['payment_status']??'pending'))?>"><?=e(payment_status_label($s['payment_status']??'pending'))?></span></td><td><span class="badge badge-<?=e($state['class'])?>"><?=e($state['label'])?></span></td><td><div class="actions"><?php if(has_permission('services.edit')):?><a class="btn btn-light btn-small" href="service_form.php?id=<?=(int)$s['id']?>">Editar</a><?php endif;?><?php if(has_permission('services.renew')):?><a class="btn btn-secondary btn-small" href="service_renew.php?id=<?=(int)$s['id']?>">Renovar</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<div class="dashboard-grid" style="margin-top:18px"><section class="panel" id="deals"><div class="panel-header"><h2>Negocios y oportunidades</h2></div><div class="panel-body metric-list"><?php if(!$deals):?><div class="empty">Sin negocios.</div><?php endif;?><?php foreach($deals as$d):?><div class="metric-row"><span><a class="table-title" href="deal_view.php?id=<?=(int)$d['id']?>"><?=e($d['title'])?></a><small><?=e($d['stage_name'].' · '.$d['probability'].'% · '.($d['owner_name']?:'Sin responsable'))?></small></span><strong><?=e(format_money($d['amount'],$d['currency']))?></strong></div><?php endforeach;?></div></section><section class="panel" id="quotes"><div class="panel-header"><h2>Cotizaciones</h2></div><div class="panel-body metric-list"><?php if(!$quotes):?><div class="empty">Sin cotizaciones.</div><?php endif;?><?php foreach($quotes as$q):?><div class="metric-row"><span><a class="table-title" href="quotation_view.php?id=<?=(int)$q['id']?>"><?=e($q['quotation_number'])?></a><small><?=e(quote_status_label($q['status']).' · '.format_date($q['issue_date']))?></small></span><strong><?=e(format_money($q['total'],$q['currency']))?></strong></div><?php endforeach;?></div></section></div>

<section class="panel" id="billing" style="margin-top:18px"><div class="panel-header"><div><h2>Facturación y renovaciones</h2><span class="table-sub">Cobros, mensualidades, renovaciones y pagos del cliente.</span></div><div class="actions"><a class="btn btn-secondary btn-small" href="billing_services.php?q=<?=urlencode($client['company_name'])?>">VER EN FACTURACIÓN</a><?php if(has_permission('payments.manage')):?><a class="btn btn-primary btn-small" href="payment_form.php?client_id=<?=$id?>">+ REGISTRAR PAGO</a><?php endif;?></div></div><div class="stats-grid compact-stats"><?php foreach($billingTotals as$cur=>$amt):?><div class="stat-card"><small>MRR <?=e($cur)?></small><strong><?=e(format_money($amt,$cur))?></strong><span>Servicios mensuales activos</span></div><?php endforeach;?></div><div class="table-wrap"><?php if(!$billingCharges):?><div class="empty">No hay ciclos de cobro registrados todavía.</div><?php else:?><table class="data-table"><thead><tr><th>Servicio</th><th>Vencimiento</th><th>Valor</th><th>Estado</th><th>Pagado</th><th></th></tr></thead><tbody><?php foreach($billingCharges as$bc):?><tr><td><?=e($bc['service_name'])?></td><td><?=e(format_date($bc['due_date']))?></td><td><?=e(format_money($bc['amount'],$bc['currency']))?></td><td><span class="badge badge-<?=e(billing_status_class($bc['status']))?>"><?=e(billing_status_label($bc['status']))?></span></td><td><?=e(format_date($bc['paid_at']))?></td><td><?php if($bc['status']!=='paid'&&has_permission('payments.manage')):?><a class="btn btn-primary btn-small" href="billing_charge_pay.php?id=<?=(int)$bc['id']?>">REGISTRAR PAGO</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<section class="panel" id="activity" style="margin-top:18px"><div class="panel-header"><div><h2>Línea de tiempo de actividades</h2><span class="table-sub">Tareas, eventos, llamadas, correos y reuniones.</span></div><a class="btn btn-light btn-small" href="activity_form.php?client_id=<?=$id?>">+ Actividad</a></div><div class="panel-body activity-timeline"><?php if(!$activities):?><div class="empty">No hay actividades.</div><?php endif;?><?php foreach($activities as$a):?><article class="activity-entry <?=$a['status']==='completed'?'completed':''?>"><div class="activity-entry-icon"><?=crm_icon('activity')?></div><div><h4><?=e($a['subject'])?></h4><p><?=e($a['details']?:'')?></p><small><?=e(activity_type_label($a['activity_type']).' · '.($a['contact_name']?:$a['deal_title']?:'General').' · '.($a['assigned_name']?:'Sin asignar'))?></small></div><time><?=e($a['due_at']?(new DateTimeImmutable($a['due_at']))->format('d/m/Y H:i'):'Sin fecha')?></time></article><?php endforeach;?></div></section>
<?php if($client['notes']):?><section class="panel" style="margin-top:18px"><div class="panel-header"><h2>Notas internas</h2></div><div class="panel-body" style="white-space:pre-wrap"><?=e($client['notes'])?></div></section><?php endif;?><?php if(has_permission('projects.view')):?><section class="panel"><div class="panel-header"><div><h2>Proyectos del cliente</h2><span class="table-sub">Ejecución vinculada a este cliente.</span></div><?php if(has_permission('projects.manage')):?><a class="btn btn-light btn-small" href="project_form.php?client_id=<?=$id?>">+ Proyecto</a><?php endif;?></div><div class="panel-body metric-list"><?php if(!$pmProjects):?><div class="empty">Sin proyectos asociados.</div><?php endif;?><?php foreach($pmProjects as$pr):?><div class="metric-row"><span><a class="table-title" href="project_view.php?id=<?=$pr['id']?>"><?=e($pr['name'])?></a><small class="table-sub"><?=e(pm_status_label($pr['status']))?> · <?=e(pm_health_label($pr['health']))?> · <?=e(pm_date($pr['due_date']))?></small></span><strong><?=(int)$pr['progress']?>%</strong></div><?php endforeach;?></div></section><?php endif;?>
